let
    Config = Excel.CurrentWorkbook(){[Name="tConfig"]}[Content],
    Param = (k as text) => Text.From(Config{[Parametro=k]}[Valor]),
    Clean = (v as any) as text => if v=null then "" else Text.Trim(Text.From(v)),
    Tokens = (v as text) as list => List.Select(Text.SplitAny(v," #(lf)#(cr)#(tab)"),each _<>""),
    Join = (v as list) as text => Text.Combine(List.Combine(List.Transform(v,each Tokens(Clean(_))))," "),
    Digits = (s as text,n as number) as logical => Text.Length(s)=n and Text.Select(s,{"0".."9"})=s,
    Num = (v as any) as number => if Value.Is(v,type number) then v else Number.FromText(Clean(v),"en-US"),
    BlankZero = (v as any) as number => if Clean(v)="" then 0 else Num(v),
    Year = if Param("Ejercicio")="2026" then 2026 else error "Esta versión requiere ejercicio 2026 y cartera PMI 2026–2029.",
    PDFPath = Param("PDF"),
    Pages = Table.SelectRows(Pdf.Tables(File.Contents(PDFPath),[Implementation="1.3",MultiPageTables=false]),each [Kind]="Page"),
    PageRows = List.Combine(List.Transform(Table.ToRecords(Pages),(p)=>
        let lines=List.Transform(Table.ToRows(p[Data]),each Join(_)),
            uline=List.First(List.Select(lines,each Text.Contains(_,"UNIDAD EJECUTORA:"))),
            ue=Text.Start(Text.Trim(Text.AfterDelimiter(uline,"UNIDAD EJECUTORA:")),3),
            fline=List.First(List.Select(lines,each Text.Contains(_,"Fecha:"))),
            fecha=Text.Start(Text.Trim(Text.AfterDelimiter(fline,"Fecha:")),10),
            valid=List.AnyTrue(List.Transform(lines,each Text.Contains(_,"CERTIFICACIÓN Vs MARCO INICIAL"))) and List.AnyTrue(List.Transform(lines,each Text.Contains(_,"458 - GOBIERNO REGIONAL"))) and List.AnyTrue(List.Transform(lines,each Text.Contains(_,"AÑO "&Text.From(Year))))
        in if not valid then error "El PDF no corresponde al reporte de certificación del pliego 458 / ejercicio 2026."
        else List.Transform(lines,(s)=>let tk=Tokens(s),first=if List.IsEmpty(tk) then "" else tk{0},isName=Digits(first,7) in [UE=ue,Texto=s,FechaPDF=fecha,Pagina=p[Id],CodigoNombre=if isName then first else null,Nombre=if isName then Text.Combine(List.Skip(tk)," ") else null]))),
    Lines = Table.FillDown(Table.FromRecords(PageRows),{"CodigoNombre","Nombre"}),
    TotalLines = Table.SelectRows(Lines,each Text.StartsWith([Texto],"TOTAL PRODUCTO/PROYECTO ") or Text.StartsWith([Texto],"TOTAL UNIDAD EJECUTORA ") or Text.StartsWith([Texto],"TOTAL PLIEGO:")),
    ParseTotals = List.Transform(Table.ToRecords(TotalLines),(r)=>
        let kind=if Text.StartsWith(r[Texto],"TOTAL PRODUCTO") then "Proyecto" else if Text.StartsWith(r[Texto],"TOTAL UNIDAD") then "UE" else "Pliego",
            tail=if kind="Proyecto" then Text.AfterDelimiter(r[Texto],"TOTAL PRODUCTO/PROYECTO ") else Text.AfterDelimiter(r[Texto],":"),
            tk=Tokens(tail),code=if kind="Proyecto" then tk{0} else "",vals=List.Transform(if kind="Proyecto" then List.Skip(tk) else tk,Num),
            n=if List.Count(vals)=17 then vals else error "Columnas inesperadas en total PDF: "&r[Pagina]&" / "&r[Texto]
        in [Tipo=kind,UE=r[UE],CUI=code,Nombre=if kind="Proyecto" and code=r[CodigoNombre] then r[Nombre] else if kind="Proyecto" then error "No se encontró el nombre del proyecto "&code else "",PIA=n{0},Modificaciones=n{1},PIM=n{2},Certificacion=n{15},Saldo=n{16},FechaPDF=r[FechaPDF],Pagina=r[Pagina]]),
    PDFAll = Table.Buffer(Table.FromRecords(ParseTotals)),
    PDFDetails = Table.SelectRows(PDFAll,each [Tipo]="Proyecto"),
    PDF = Table.Group(PDFDetails,{"UE","CUI"},{{"Nombre",each List.First([Nombre]),type text},{"PIA",each List.Sum([PIA]),type number},{"Modificaciones",each List.Sum([Modificaciones]),type number},{"PIM",each List.Sum([PIM]),type number},{"Certificacion",each List.Sum([Certificacion]),type number},{"Saldo",each List.Sum([Saldo]),type number},{"Fecha PDF",each Text.Combine(List.Distinct([FechaPDF])," / "),type text},{"Pagina",each Text.Combine(List.Distinct([Pagina]),", "),type text}}),
    PDFTotals = Table.SelectRows(PDFAll,each [Tipo]="UE"),
    Grand = Table.SelectRows(PDFAll,each [Tipo]="Pliego"){0},
    Metrics={"PIA","Modificaciones","PIM","Certificacion","Saldo"},
    PDFChecks = List.Combine({List.Transform(Metrics,(k)=>[Control=k&" PDF pliego",Fuente="PDF",Calculado=List.Sum(Table.Column(PDF,k)),Referencia=Record.Field(Grand,k)]),List.Combine(List.Transform(Table.ToRecords(PDFTotals),(r)=>List.Transform(Metrics,(k)=>[Control=r[UE]&" "&k,Fuente="PDF UE",Calculado=List.Sum(Table.Column(Table.SelectRows(PDF,each [UE]=r[UE]),k)),Referencia=Record.Field(r,k)])))}),
    UEs = {"001","002","003","005","100","302","413"},
    ValidPDF = List.AllTrue(List.Transform(PDFChecks,each Number.Abs([Calculado]-[Referencia])<0.02)) and List.Count(List.Difference(UEs,List.Distinct(PDF[UE])))=0 and List.Count(List.Difference(List.Distinct(PDF[UE]),UEs))=0 and List.Count(List.Distinct(PDFDetails[FechaPDF]))=1 and Table.RowCount(Table.SelectRows(PDF,each Number.Abs([PIA]+[Modificaciones]-[PIM])>0.02 or Number.Abs([PIM]-[Certificacion]-[Saldo])>0.02))=0,

    EW = Excel.Workbook(File.Contents(Param("Ejecucion")),null,true),
    ETable = EW{[Name="resumen_marco"]}[Data],
    ERows = Table.ToRows(ETable),
    ELabels = List.Transform(ERows,each Clean(_{1})),
    EValidHeader = Text.Contains(ELabels{0},Text.From(Year)) and Text.Contains(ELabels{1},"RESUMEN DEL MARCO") and Text.Contains(ELabels{5},"458 -") and Text.Contains(ELabels{6},"UNIDAD EJECUTORA: 001 -"),
    ERecords = List.Transform(ERows,(r)=>let label=Clean(r{1}),tk=Tokens(label),head=List.Count(tk)>=4 and Digits(tk{0},4) and Digits(tk{1},4) and Digits(tk{2},7),rub=List.Count(tk)>1 and Digits(tk{0},2) in [Texto=label,Raw=r,CUI=if head then tk{2} else null,Meta=if head then tk{0} else null,Rubro=if rub then tk{0} else null]),
    EFill = Table.FillDown(Table.FromRecords(ERecords),{"CUI","Meta","Rubro"}),
    EMetas = Table.SelectRows(EFill,each Text.StartsWith([Texto],"TOTAL META ")),
    EData = Table.FromRecords(List.Transform(Table.ToRecords(EMetas),(r)=>let n=r[Raw] in if r[CUI]=null or r[Meta]<>Text.AfterDelimiter(r[Texto],"TOTAL META ") then error "Meta sin proyecto en XLS" else [UE="001",CUI=r[CUI],Meta=r[Meta],Rubro=r[Rubro],PIA=BlankZero(n{5}),PIM=BlankZero(n{7}),Certificacion=BlankZero(n{9}),Compromiso=BlankZero(n{13}),Devengado=BlankZero(n{17})])),
    FooterIndex = List.PositionOf(ELabels,"TOTAL UNIDAD EJECUTORA 001:"),
    EF = if FooterIndex<0 then error "No se encontró total UE 001 en XLS" else ERows{FooterIndex+1},
    EReference = [PIA=Num(EF{6}),PIM=Num(EF{8}),Certificacion=Num(EF{9}),Compromiso=Num(EF{13}),Devengado=Num(EF{17})],
    EChecks = List.Transform({"PIA","PIM","Certificacion","Compromiso","Devengado"},(k)=>[Control=k&" UE 001",Fuente="Excel ejecución",Calculado=List.Sum(Table.Column(EData,k)),Referencia=Record.Field(EReference,k)]),
    ValidE = EValidHeader and List.AllTrue(List.Transform(EChecks,each Number.Abs([Calculado]-[Referencia])<0.02)),
    EAgg = Table.Group(EData,{"UE","CUI"},List.Transform({"PIA","PIM","Certificacion","Compromiso","Devengado"},(k)=>{k,(t)=>List.Sum(Table.Column(t,k)),type number})),
    MissingE = Table.RowCount(Table.NestedJoin(EAgg,{"UE","CUI"},PDF,{"UE","CUI"},"P",JoinKind.LeftAnti)),

    PW = Excel.Workbook(File.Contents(Param("PMI")),null,true),
    PT = Table.PromoteHeaders(Table.Skip(PW{[Item="Cartera",Kind="Sheet"]}[Data],5),[PromoteAllScalars=true]),
    PKeep = Table.SelectColumns(PT,{"Código Único","Nombre de inversión","Tipo inversión","Prioridad","Orden prelación","Costo actualizado (S/)","Devengado acumulado (S/) (al 31 dic. 2025)","PIM 2026 (S/)","Monto Año 2026 (S/)","Monto Año 2027 (S/)","Monto Año 2028 (S/)","Monto Año 2029 (S/)"}),
    PRename = Table.RenameColumns(PKeep,List.Zip({Table.ColumnNames(PKeep),{"CUI","Nombre","Tipo","Prioridad","Prelacion","Costo actualizado","Devengado hasta 2025","PIM PMI 2026","PMI 2026","PMI 2027","PMI 2028","PMI 2029"}})),
    PType = Table.TransformColumns(PRename,{{"CUI",each Clean(_),type text}}),
    PData = Table.SelectRows(PType,each [CUI]<>""),
    PMI = Table.AddColumn(PData,"Fecha PMI",each Param("Fecha PMI"),type text),
    ValidPMI = Table.RowCount(PMI)>0 and Table.RowCount(PMI)=List.Count(List.Distinct(PMI[CUI])),
    Checks = Table.AddColumn(Table.FromRecords(PDFChecks&EChecks),"Diferencia",each [Calculado]-[Referencia],type number),
    ChecksText = Table.AddColumn(Checks,"Resultado",each if Number.Abs([Diferencia])<0.02 then "Conciliado" else "Revisar",type text),
    Valid = ValidPDF and ValidE and ValidPMI and MissingE=0
in
    [PDF=if ValidPDF then PDF else error "PDF no conciliado: revise columnas, UE y totales.",PDFFilas=Table.RowCount(PDFDetails),PDFGrand=Grand,PDFTotals=PDFTotals,Ejecucion=if ValidE then EData else error "Excel SIAF incompatible o no conciliado.",EAgg=if ValidE then EAgg else error "Excel SIAF incompatible o no conciliado.",ERef=EReference,PMI=if ValidPMI then PMI else error "Cartera PMI vacía o con códigos duplicados.",Control=if Valid then ChecksText else error "Fuentes incompatibles o conciliación fallida. Revise pliego, ejercicio, UE, estructura, duplicados PMI y totales.",Config=Config,MissingE=MissingE]
